uniform float amzp_usePos;
uniform float amzp_useScale;
uniform float amzp_useAngle;


        void amzRender() {

            float angle = abs(amzAngularVelocity) * (amzp_shutter/360.0) * amzp_tune; 
            float cx = amzp_PANGLE.x + amzPivot.x/layer.x;
            float cy = amzp_PANGLE.y - amzPivot.y/layer.y;
            float2 image_size = getTexSize((screen.zw/1.0));
            float maxF = max(screen.zw.x, screen.zw.y);
            float2 texelSize = 1.0 / float2(maxF, maxF);
            float2 center = (float4(cx,cy,0.0,1.0) * amzLayerToScreen()).xy;
            float2 v = amzScreenNorm().st - center;
            v.y *= image_size.y / image_size.x;
            float r = length(v);
            float d = 6.283185*r;
            float l = d*angle/360.0;
            float a = angle * 0.0174533; 
            float speed = l/texelSize.x;
            int nMax = int(amzp_samples + 1.5);
            int nSamples = int(clamp(speed, 1.01, float(nMax)+0.01));
