                t = clamp(t, -0.5, 0.5);
                float sampleAngle = t * a;
                float s = sin(sampleAngle);
                float c = cos(sampleAngle);
                float2x2 rot = float2x2(c, -s, s, c);
                float2 temp = v*rot;
                temp.y = temp.y * image_size.x / image_size.y;
                float w = 1.0 - abs(t*2.0); 
                float4 col = amzTexture(0, center + temp);
                accum += col * w;
                wsum += w;
            }
            float4 base = amzTexture(0, amzScreenNorm().st);
            amzOutput = (accum + base) / (wsum + 1.0);
        }


